// Generated by `just generate` from `src/plugins/claudetto/slices/decide/lab/second-opinion.test.ts`. Edit the source and run `just generate`.
// The hook lab of the `decide` slice: `claude plugin test plugins/claudetto` runs the tool `second_opinion` with stubs.
// The stub of `process.run` stands for the Jev CLI and records each run, so no network call goes out.
// The stub of `model.complete` answers for the fallback model, and it records the request that the fallback gets.

import type { ModelCompleteResult, On, PluginOptions } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

// The input of the tool, for the typed `$.tool.call` of this test.
// A declaration in the author's project adds the MCP tool to `McpToolInputs`.
declare module "claude-code" {
  interface McpToolInputs {
    mcp__claudetto__second_opinion: { question: string };
  }
}

const NO_USAGE = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};

/** What the stubs record: the prompts of the fallback model, and the argument lists of the process runs. */
type Seen = { prompts: string[]; runs: (readonly string[])[] };

/** Stubs for one test. `jev` is the run that the CLI gives, and `answer` is the text of the fallback model, or `null` for no reply. */
const stub = (
  on: On,
  answer: string | null,
  jev = { exitCode: 0, stdout: "", stderr: "" },
): Seen => {
  const seen: Seen = { prompts: [], runs: [] };
  mock.env(on, { TYPESAFE_API_KEY: "typesafe-key" });
  const reply: ModelCompleteResult =
    answer === null
      ? {
          isAnswered: false,
          reason: "api-error",
          status: null,
          error: "unknown",
          usage: NO_USAGE,
        }
      : { isAnswered: true, text: answer, usage: NO_USAGE };
  on("model.complete", (_$, e) => {
    seen.prompts.push(e.prompt);
    return { value: reply };
  });
  on("process.run", (_$, e) => {
    seen.runs.push(e.argv);
    return {
      value: { ...jev, isStdoutTruncated: false, isStderrTruncated: false },
    };
  });
  return seen;
};

const CLAUDE: { options: PluginOptions } = { options: { decide: "claude" } };
const JEV: { options: PluginOptions } = { options: { decide: "jev" } };
const MODEL_YES = '{"choice":"yes","confidence":0.8,"reason":"cheap"}';
const JEV_YES = JSON.stringify({
  text: "yes, 0.9",
  answer: { choice: "yes", confidence: 0.9 },
});

const ask = ($: Engine, input: Record<string, unknown>) =>
  $.tool.call({
    tool: "mcp__claudetto__second_opinion",
    question: "Use the cache?",
    ...input,
  });

test(
  // biome-ignore lint/plugin: a test name that a `slice.ts` file references
  "with the option `claude` and a key, the model answers and no process runs",
  CLAUDE,
  async ($: Engine, on: On) => {
    const seen = stub(on, MODEL_YES);
    const { result } = await ask($, {});
    expect(String(result)).toContain("yes");
    expect(seen.prompts).toHaveLength(1);
    expect(seen.prompts[0]).toContain("Use the cache?");
    expect(seen.runs).toEqual([]);
  },
);

test(
  // biome-ignore lint/plugin: a test name that a `slice.ts` file references
  "with the option `jev`, Jev answers and the model gets no request",
  JEV,
  async ($: Engine, on: On) => {
    const seen = stub(on, MODEL_YES, {
      exitCode: 0,
      stdout: JEV_YES,
      stderr: "",
    });
    const { result } = await ask($, {});
    expect(String(result)).toContain("Jev answered");
    expect(seen.runs).toHaveLength(1);
    expect(seen.prompts).toEqual([]);
  },
);

test(
  // biome-ignore lint/plugin: a test name that a `slice.ts` file references
  "a failed run of Jev goes to the model, and the error text of the run is in the result",
  JEV,
  async ($: Engine, on: On) => {
    const seen = stub(on, MODEL_YES, {
      exitCode: 1,
      stdout: "",
      stderr: "socket closed",
    });
    const { result } = await ask($, {});
    expect(String(result)).toContain("socket closed");
    expect(seen.prompts).toHaveLength(1);
  },
);

test(
  // biome-ignore lint/plugin: a test name that a `slice.ts` file references
  "a model with no reply still gets one request and does not throw",
  CLAUDE,
  async ($: Engine, on: On) => {
    const seen = stub(on, null);
    await ask($, {});
    expect(seen.prompts).toHaveLength(1);
  },
);

test(
  "a call with no question sends no request",
  JEV,
  async ($: Engine, on: On) => {
    const seen = stub(on, MODEL_YES);
    await ask($, { question: " " });
    expect(seen.prompts).toEqual([]);
    expect(seen.runs).toEqual([]);
  },
);

test(
  "two options with one key send no request",
  JEV,
  async ($: Engine, on: On) => {
    const seen = stub(on, MODEL_YES);
    const { result } = await ask($, { options: [{ key: "a" }, { key: "a" }] });
    expect(String(result)).toContain("same `key`");
    expect(seen.prompts).toEqual([]);
    expect(seen.runs).toEqual([]);
  },
);
